const saveVisitTotals = `-- name: SaveVisitTotals :execrows
INSERT INTO app.visit_totals (day, visitors, signed_in, pageviews)
SELECT v.day, count(*), count(v.user_id), sum(v.pageviews) FROM app.daily_visits v WHERE v.day < $1::date GROUP BY v.day
ON CONFLICT (day) DO UPDATE SET visitors = excluded.visitors, signed_in = excluded.signed_in, pageviews = excluded.pageviews
`

// Copies the daily totals of past days (before today) into visit_totals, before the per-visitor rows are deleted.
func (q *Queries) SaveVisitTotals(ctx context.Context, today pgtype.Date) (int64, error) {
	result, err := q.db.Exec(ctx, saveVisitTotals, today)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

