const visitTotalsBetween = `-- name: VisitTotalsBetween :many
WITH days AS (SELECT generate_series($1::date, $2::date, interval '1 day')::date AS day)
SELECT d.day, coalesce(l.visitors, t.visitors, 0)::int AS visitors, coalesce(l.signed_in, t.signed_in, 0)::int AS signed_in,
       coalesce(l.pageviews, t.pageviews, 0)::int AS pageviews
FROM days d
LEFT JOIN (
  SELECT v.day, count(*)::int AS visitors, count(v.user_id)::int AS signed_in, sum(v.pageviews)::int AS pageviews
  FROM app.daily_visits v WHERE v.day BETWEEN $1::date AND $2::date GROUP BY v.day
) l ON l.day = d.day
LEFT JOIN app.visit_totals t ON t.day = d.day
ORDER BY d.day DESC
`

type VisitTotalsBetweenParams struct {
	FromDay pgtype.Date
	ToDay   pgtype.Date
}

type VisitTotalsBetweenRow struct {
	Day       pgtype.Date
	Visitors  int32
	SignedIn  int32
	Pageviews int32
}

// Each day from from_day to to_day, newest first: visitor totals from the per-visitor rows while they're kept (90 days),
// else from the saved totals (days without visits are 0).
func (q *Queries) VisitTotalsBetween(ctx context.Context, arg VisitTotalsBetweenParams) ([]VisitTotalsBetweenRow, error) {
	rows, err := q.db.Query(ctx, visitTotalsBetween, arg.FromDay, arg.ToDay)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []VisitTotalsBetweenRow{}
	for rows.Next() {
		var i VisitTotalsBetweenRow
		if err := rows.Scan(
			&i.Day,
			&i.Visitors,
			&i.SignedIn,
			&i.Pageviews,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const visitTotalsOfDay = `-- name: VisitTotalsOfDay :one
SELECT coalesce(l.visitors, t.visitors, 0)::int AS visitors, coalesce(l.signed_in, t.signed_in, 0)::int AS signed_in,
       coalesce(l.pageviews, t.pageviews, 0)::int AS pageviews
FROM (SELECT 1) one
LEFT JOIN (
  SELECT count(*)::int AS visitors, count(v.user_id)::int AS signed_in, sum(v.pageviews)::int AS pageviews
  FROM app.daily_visits v WHERE v.day = $1::date HAVING count(*) > 0
) l ON true
LEFT JOIN app.visit_totals t ON t.day = $1::date
`

type VisitTotalsOfDayRow struct {
	Visitors  int32
	SignedIn  int32
	Pageviews int32
}

// One day's visitor totals: from the per-visitor rows while they're kept (90 days), else from the saved totals.
func (q *Queries) VisitTotalsOfDay(ctx context.Context, day pgtype.Date) (VisitTotalsOfDayRow, error) {
	row := q.db.QueryRow(ctx, visitTotalsOfDay, day)
	var i VisitTotalsOfDayRow
	err := row.Scan(&i.Visitors, &i.SignedIn, &i.Pageviews)
	return i, err
}
